1732:     fn materialize_input_bindings(
1733:         &self,
1734:         request: &TaskRunRequest,
1735:         request_identity_digest: &str,
1736:         job_id: &str,
1737:         inputs: &[InputBindingRequest],
1738:     ) -> RuntimeResult<PreparedInputSet> {
1739:         let set_digest = sha256_bytes(
1740:             format!(
1741:                 "{}\0{}\0{}",
1742:                 request.principal, request.client_request_id, request_identity_digest
1743:             )
1744:             .as_bytes(),
1745:         );
1746:         let input_set_id = set_digest
1747:             .strip_prefix("sha256:")
1748:             .unwrap_or(&set_digest)
1749:             .to_string();
1750:         let materialization_root = self.executor.input_materializations_root();
1751:         fs::create_dir_all(&materialization_root)
1752:             .map_err(|error| io_error("create input materialization root", error))?;
1753:         let prepared_root = materialization_root.join(job_id);
1754:         let owned_root = self.executor.job_input_path(job_id);
1755:         if prepared_root.exists() || owned_root.exists() {
1756:             return Err(RuntimeError::new(
1757:                 RuntimeErrorCode::RegistryCorrupt,
1758:                 "preallocated immutable input identity already has physical state",
1759:                 Some("jobId"),
1760:                 false,
1761:             ));
1762:         }
1763: 
1764:         let lease_path = materialization_root.join(format!(".{job_id}.lease"));
1765:         let lease = OpenOptions::new()
1766:             .read(true)
1767:             .write(true)
1768:             .create_new(true)
1769:             .mode(0o600)
1770:             .open(&lease_path)
1771:             .map_err(|error| io_error("create input staging lease", error))?;
1772:         if unsafe { libc::flock(lease.as_raw_fd(), libc::LOCK_EX | libc::LOCK_NB) } != 0 {
1773:             let error = std::io::Error::last_os_error();
1774:             let _ = fs::remove_file(&lease_path);
1775:             return Err(io_error("lock input staging lease", error));
1776:         }
1777:         let staging = materialization_root.join(format!(".{job_id}.staging-{}", Uuid::now_v7()));
1778:         let result = (|| {
1779:             fs::create_dir(&staging)
1780:                 .map_err(|error| io_error("create input staging directory", error))?;
1781:             fs::set_permissions(&staging, fs::Permissions::from_mode(0o700))
1782:                 .map_err(|error| io_error("protect input staging directory", error))?;
1783:             for (index, input) in inputs.iter().enumerate() {
1784:                 let authority = self
1785:                     .input_authorities
1786:                     .get(&input.authority)
1787:                     .ok_or_else(|| {
1788:                         RuntimeError::invalid(
1789:                             format!("unknown input authority {}", input.authority),
1790:                             &format!("inputs[{index}].authority"),
1791:                         )
1792:                     })?;
1793:                 let source =
1794:                     open_authority_file(authority.root.as_ref(), &input.relative_object, index)?;
1795:                 let target = staging.join(&input.presentation_relative_path);
1796:                 if let Some(parent) = target.parent() {
1797:                     fs::create_dir_all(parent)
1798:                         .map_err(|error| io_error("create input presentation tree", error))?;
1799:                 }
1800:                 let observed_digest = copy_input_and_digest(source, &target)?;
1801:                 if observed_digest != input.expected_digest {
1802:                     return Err(RuntimeError::invalid(
1803:                         format!(
1804:                             "materialized input digest mismatch: expected {}, observed {observed_digest}",
1805:                             input.expected_digest
1806:                         ),
1807:                         &format!("inputs[{index}].expectedDigest"),
1808:                     ));
1809:                 }
1810:                 fs::set_permissions(&target, fs::Permissions::from_mode(0o444))
1811:                     .map_err(|error| io_error("protect materialized input", error))?;
1812:             }
1813:             sync_directory(&staging)?;
1814:             fs::rename(&staging, &prepared_root)
1815:                 .map_err(|error| io_error("publish prepared immutable input set", error))?;
1816:             sync_directory(&materialization_root)?;
1817:             let effective_inputs = verify_effective_input_set(&prepared_root, inputs)?;
1818:             Ok(PreparedInputSet {
1819:                 input_set_id,
1820:                 prepared_root: prepared_root.clone(),
1821:                 effective_inputs,
1822:             })
1823:         })();
1824:         if result.is_err() {
1825:             let _ = fs::remove_dir_all(&staging);
1826:             let _ = fs::remove_dir_all(&prepared_root);
1827:         }
1828:         drop(lease);
1829:         let _ = fs::remove_file(&lease_path);
1830:         let _ = sync_directory(&materialization_root);
1831:         result
1832:     }
